(function(){
  const variants=['void-eye','fracture','spiral','inverse','thorn','black-sun','cage','hourglass','chimera','glass','coin','rust','phoenix','shield','void','tongue','flesh','upward','hunger','bullet','eye','bones','vault','shadow','gallery','star','scales','reverse','cube','requiem'];
  window.envoltoRitualSigil=function(index){
    const i=Math.max(1,Number(index)||1), v=variants[(i-1)%variants.length];
    const cx=32,cy=32,rot=(i*17)%360, r=21+(i%5);
    let glyph='<circle cx="32" cy="32" r="6"/>';
    if(v==='void-eye') glyph+='<ellipse cx="32" cy="32" rx="15" ry="8"/><circle cx="32" cy="32" r="3"/>';
    else if(v==='fracture') glyph+='<path d="M12 14l10 11-8 7 13 6-6 12M52 14L42 25l8 7-13 6 6 12"/>';
    else if(v==='spiral') glyph+='<path d="M32 11c12 0 18 8 18 17 0 11-7 19-18 19-9 0-15-6-15-14 0-7 5-12 12-12 5 0 9 3 9 8 0 3-2 6-6 6"/>';
    else if(v==='inverse') glyph+='<polygon points="32,8 54,48 10,48"/><path d="M18 16l28 32M46 16L18 48"/>';
    else if(v==='thorn') glyph+='<path d="M10 43l12-18 10 12 10-22 12 28"/>';
    else if(v==='black-sun') glyph+='<circle cx="32" cy="32" r="15"/><path d="M32 7v9M32 48v9M7 32h9M48 32h9"/>';
    else if(v==='cage') glyph+='<rect x="15" y="15" width="34" height="34"/><path d="M15 26h34M15 38h34M26 15v34M38 15v34"/>';
    else if(v==='hourglass') glyph+='<path d="M20 12h24M20 52h24M21 14c0 9 10 10 11 18-1 8-11 9-11 18M43 14c0 9-10 10-11 18 1 8 11 9 11 18"/>';
    else if(v==='chimera') glyph+='<path d="M18 46c-8-11 0-21 9-18 4-10 16-11 20-2 3 8-1 17-9 20-7 3-16 1-20 0Z"/><path d="M25 32l-5-8M39 29l5-9"/>';
    else if(v==='glass') glyph+='<path d="M14 12h36l-4 13-10 7 10 8-4 12H22l-4-12 10-8-10-7z"/>';
    else if(v==='coin') glyph+='<circle cx="32" cy="32" r="16"/><path d="M24 25c10-6 19 5 4 9-9 2 0 10 10 4"/>';
    else if(v==='rust') glyph+='<path d="M18 10v14l7 7-7 7v16M46 10v14l-7 7 7 7v16M18 32h28"/>';
    else if(v==='phoenix') glyph+='<path d="M32 51c-12-6-18-14-12-23 3-5 8-7 12-8 4 1 9 3 12 8 6 9 0 17-12 23ZM32 20V8M24 14l8 7 8-7"/>';
    else if(v==='shield') glyph+='<path d="M32 9l17 6v12c0 12-7 20-17 27-10-7-17-15-17-27V15z"/><path d="M24 31l6 6 11-13"/>';
    else if(v==='void') glyph+='<circle cx="32" cy="32" r="13"/><path d="M18 18l28 28M46 18L18 46"/>';
    else if(v==='tongue') glyph+='<path d="M20 16c7 0 9 7 12 16 3-9 5-16 12-16v12c0 12-7 18-12 20-5-2-12-8-12-20z"/>';
    else if(v==='flesh') glyph+='<path d="M14 22c8-7 12 4 18-1 6-5 10 6 18-1M14 40c8-7 12 4 18-1 6-5 10 6 18-1"/>';
    else if(v==='upward') glyph+='<path d="M32 52V13M18 27l14-14 14 14M22 40l10-10 10 10"/>';
    else if(v==='hunger') glyph+='<path d="M17 18c6-5 24-5 30 0v14c0 10-7 18-15 22-8-4-15-12-15-22z"/><circle cx="27" cy="30" r="3"/><circle cx="37" cy="30" r="3"/>';
    else if(v==='bullet') glyph+='<path d="M19 39l18-18 10 2 6 10-10 10-10-6-4 4z"/>';
    else if(v==='eye') glyph+='<path d="M10 32s9-13 22-13 22 13 22 13-9 13-22 13S10 32 10 32Z"/><circle cx="32" cy="32" r="6"/>';
    else if(v==='bones') glyph+='<path d="M18 18l10 10M46 18L36 28M18 46l10-10M46 46L36 36"/><circle cx="17" cy="17" r="5"/><circle cx="47" cy="17" r="5"/><circle cx="17" cy="47" r="5"/><circle cx="47" cy="47" r="5"/>';
    else if(v==='vault') glyph+='<rect x="17" y="13" width="30" height="38" rx="4"/><circle cx="32" cy="30" r="7"/><path d="M32 23v14M25 30h14"/>';
    else if(v==='shadow') glyph+='<path d="M20 49c-8-9 0-18 5-22-1-7 4-13 11-14 8-1 14 5 13 12 7 7 4 18-4 22-9 5-19 6-25 2Z"/>';
    else if(v==='gallery') glyph+='<rect x="13" y="13" width="38" height="38"/><path d="M19 19l26 26M45 19L19 45M32 13v38M13 32h38"/>';
    else if(v==='star') glyph+='<path d="M32 8l6 16 17 1-13 10 4 17-14-10-14 10 4-17-13-10 17-1z"/>';
    else if(v==='scales') glyph+='<path d="M32 10v38M18 19h28M14 20l-7 14h14zM50 20l-7 14h14zM23 52h18"/>';
    else if(v==='reverse') glyph+='<path d="M18 44c14 10 29 1 27-15-1-9-6-15-13-18M23 18l9-7 9 7"/>';
    else if(v==='cube') glyph+='<path d="M18 20l14-9 14 9v24l-14 9-14-9zM18 20l14 9 14-9M32 29v24"/>';
    else glyph+='<circle cx="32" cy="32" r="17"/><path d="M17 17l30 30M47 17L17 47"/>';
    return `<span class="envolto-ritual-sigil envolto-sigil-${v}" data-ritual-symbol="${i}"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="32" cy="32" r="25"/>${glyph}</svg></span>`;
  };
})();

