    const ns='http://www.w3.org/2000/svg';
    const dx=x2-x1,dy=y2-y1,len=Math.max(1,Math.hypot(dx,dy));
    const ux=dx/len,uy=dy/len,px=-uy,py=ux;
    const bend=Math.min(70,Math.max(18,len*.10));
    const wobble=Math.min(22,Math.max(8,len*.018));
    const sign=((Math.round(x1+y1+x2+y2)&1)===0)?1:-1;
    const mx=(x1+x2)/2+px*bend*sign, my=(y1+y2)/2+py*bend*sign;
    const q1x=x1+dx*.27+px*wobble*sign, q1y=y1+dy*.27+py*wobble*sign;
    const q2x=x1+dx*.68-px*wobble*.72*sign, q2y=y1+dy*.68-py*wobble*.72*sign;
    const path=document.createElementNS(ns,'path');
    path.setAttribute('d',`M ${x1.toFixed(1)} ${y1.toFixed(1)} Q ${q1x.toFixed(1)} ${q1y.toFixed(1)} ${mx.toFixed(1)} ${my.toFixed(1)} T ${x2.toFixed(1)} ${y2.toFixed(1)}`);
