    return `<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="32" cy="32" r="29" opacity=".24"/>${shapes[i%shapes.length]}</svg>`;
